var getAllBloodRequests = async (filters) => {
  const cacheKey = `cache:blood-requests:${JSON.stringify(filters)}`;
  const cachedData = await cache.get(cacheKey);
  if (cachedData) {
    try {
      return JSON.parse(cachedData);
    } catch {
    }
  }
  const {
    searchTerm,
    bloodGroup,
    urgency,
    status,
    page = 1,
    limit = 10,
    sortBy = "createdAt",
    sortOrder = "desc"
  } = filters;
  const andConditions = [
    { isDeleted: false }
  ];
  if (searchTerm) {
    andConditions.push({
      OR: [
        { patientName: { contains: searchTerm, mode: "insensitive" } },
        { hospitalName: { contains: searchTerm, mode: "insensitive" } },
        { hospitalAddress: { contains: searchTerm, mode: "insensitive" } }
      ]
    });
  }
  if (bloodGroup) {
    andConditions.push({ bloodGroup });
  }
  if (urgency) {
    andConditions.push({ urgency });
  }
  if (status) {
    andConditions.push({ status });
  }
  const where = { AND: andConditions };
  const parsedPage = Number(page) > 0 ? Number(page) : 1;
  const parsedLimit = Number(limit) > 0 ? Number(limit) : 10;
  const skip = (parsedPage - 1) * parsedLimit;
  const [total, result] = await Promise.all([
    prisma.bloodRequest.count({ where }),
    prisma.bloodRequest.findMany({
      where,
      skip,
      take: parsedLimit,
      orderBy: {
        [sortBy]: sortOrder === "asc" ? "asc" : "desc"
      },
      include: {
        requester: {
          omit: {
            password: true
          }
        }
      }
    })
  ]);
  const totalPages = Math.ceil(total / parsedLimit);
  const responseData = {
    meta: {
      page: parsedPage,
      limit: parsedLimit,
      total,
      totalPages
    },
    result
  };
  await cache.set(cacheKey, JSON.stringify(responseData), 30);
  return responseData;
};
