var initiateBkashPayment = async (payerId, payload, ipAddress) => {
  const bloodRequest = await prisma.bloodRequest.findUnique({
    where: { id: payload.requestId, isDeleted: false }
  });
  if (!bloodRequest) {
    throw new AppError(httpStatus13.NOT_FOUND, "Blood request not found");
  }
  if (bloodRequest.status === RequestStatus.CANCELLED) {
    throw new AppError(
      httpStatus13.BAD_REQUEST,
      "Cannot initiate payment for a cancelled blood request"
    );
  }
  const invoiceNumber = `INV-${Date.now()}-${Math.floor(Math.random() * 1e3)}`;
  const payer = await prisma.user.findUnique({
    where: { id: payerId },
    select: { phone: true }
  });
  const cleanPhone = payer?.phone?.replace(/\D/g, "") || "01770618575";
  const payerReference = cleanPhone.length === 11 ? cleanPhone : "01770618575";
  const bkashResponse = await BkashClient.createPayment({
    amount: payload.amount,
    invoiceNumber,
    payerReference
  });
  const payment = await prisma.payment.create({
    data: {
      requestId: payload.requestId,
      payerId,
      amount: payload.amount,
      paymentMethod: PaymentMethod.BKASH,
      paymentId: bkashResponse.paymentID,
      status: PaymentStatus.PENDING
    },
    include: {
      request: {
        select: {
          id: true,
          patientName: true,
          bloodGroup: true,
          hospitalName: true
        }
      },
      payer: {
        select: {
          id: true,
          name: true,
          email: true,
          phone: true
        }
      }
    }
  });
  await prisma.auditLog.create({
    data: {
      userId: payerId,
      action: "PAYMENT_INITIATED",
      resource: "Payment",
      resourceId: payment.id,
      details: {
        paymentId: payment.paymentId,
        amount: payment.amount,
        requestId: payment.requestId,
        merchantInvoiceNumber: bkashResponse.merchantInvoiceNumber
      },
      ipAddress
    }
  });
  return {
    payment,
    bkashURL: bkashResponse.bkashURL
  };
};
var handleBkashCallback = async (payload, ipAddress) => {
  const payment = await prisma.payment.findUnique({
    where: { paymentId: payload.paymentID },
    include: {
      request: true,
      payer: {
        select: {
          id: true,
          name: true,
          email: true,
          phone: true
        }
      }
    }
  });
  if (!payment) {
    throw new AppError(httpStatus13.NOT_FOUND, "Payment transaction not found");
  }
  if (payload.status === "cancel") {
    const updated = await prisma.payment.update({
      where: { id: payment.id },
      data: { status: PaymentStatus.CANCELLED }
    });
    await prisma.auditLog.create({
      data: {
        userId: payment.payerId,
        action: "PAYMENT_CANCELLED",
        resource: "Payment",
        resourceId: payment.id,
        details: { paymentId: payment.paymentId, status: "cancel" },
        ipAddress
      }
    });
    return updated;
  }
  if (payload.status === "failure") {
    const updated = await prisma.payment.update({
      where: { id: payment.id },
      data: { status: PaymentStatus.FAILED }
    });
    await prisma.auditLog.create({
      data: {
        userId: payment.payerId,
        action: "PAYMENT_FAILED",
        resource: "Payment",
        resourceId: payment.id,
        details: { paymentId: payment.paymentId, status: "failure" },
        ipAddress
      }
    });
    return updated;
  }
  if (payment.status === PaymentStatus.COMPLETED) {
    return payment;
  }
  const executeResponse = await BkashClient.executePayment(payload.paymentID);
  const completedPayment = await prisma.payment.update({
    where: { id: payment.id },
    data: {
      status: PaymentStatus.COMPLETED,
      transactionId: executeResponse.trxID,
      paymentExecuteResponse: executeResponse
    },
    include: {
      request: {
        select: {
          id: true,
          patientName: true,
          bloodGroup: true,
          hospitalName: true
        }
      },
      payer: {
        select: {
          id: true,
          name: true,
          email: true,
          phone: true
        }
      }
    }
  });
  await prisma.auditLog.create({
    data: {
      userId: payment.payerId,
      action: "PAYMENT_COMPLETED",
      resource: "Payment",
      resourceId: completedPayment.id,
      details: {
        paymentId: completedPayment.paymentId,
        transactionId: completedPayment.transactionId,
        amount: completedPayment.amount
      },
      ipAddress
    }
  });
  if (completedPayment.payer?.email) {
    sendEmail({
      to: completedPayment.payer.email,
      subject: `bKash Payment Receipt: ${completedPayment.amount} BDT (TrxID: ${completedPayment.transactionId})`,
      html: paymentReceiptEmailHtml(
        completedPayment.payer.name,
        completedPayment.amount,
        completedPayment.transactionId || "N/A",
        completedPayment.paymentId
      )
    }).catch(
      (err) => console.error("Payment receipt email dispatch error:", err)
    );
  }
  return completedPayment;
};
